import type { Transform } from './types.js'

/**
 * The result of running a single {@link Transform} via {@link runTransforms}.
 */
export type TransformRunResult = {
  /** The error thrown by the transform, if it threw. */
  error?: Error
  /** The paths of the source files the transform changed. */
  filesChanged: string[]
  /** The transform's `name`. */
  name: string
  /** Optional human-readable notes returned by the transform. */
  notes?: string[]
}

/**
 * The aggregate result of running a list of transforms via
 * {@link runTransforms}.
 */
export type RunTransformsResult = {
  /** `true` if any transform threw an error. */
  failed: boolean
  results: TransformRunResult[]
}

/**
 * Runs all supplied transforms in order against a ts-morph `Project`.
 *
 * Continues past any transform that throws, collecting results from every
 * transform. Returns `failed=true` if any transform threw an error. Each
 * transform is called with a context object of the form `{ project }`.
 */
export async function runTransforms({
  project,
  transforms,
}: {
  project: Project
  transforms: Transform[]
}): Promise<RunTransformsResult> {
  const results: TransformRunResult[] = []
  let failed = false

  for (const transform of transforms) {
    try {
      const result = await transform.apply({ project })
      results.push({
        name: transform.name,
        filesChanged: result.filesChanged,
        notes: result.notes,
      })
    } catch (error) {
      failed = true
      results.push({
        name: transform.name,
        error: error instanceof Error ? error : new Error(String(error)),
        filesChanged: [],
      })
    }
  }

  return { failed, results }
}
